from scipy.optimize import least_squares
Tf={'1/T':1/T,'sqrtT':np.sqrt(T),'logT':np.log(T),'expT':np.exp(T),'exp-T':np.exp(-T),'T^3':T**3,'1/T2':1/T**2}
def base(p,extra,place):
    a,c,d,e,g,h,i,m,n,x = p
    X=extra
    num = a + (c + d*T + m*T**2)*eps
    den = 1 + e*eps + (g*T + n*T**2)*eps + h*eps**2
    if place=='num': num = num + x*X*eps
    elif place=='exp': 
        return -eps*num/den*np.exp(-(i+x*X)*eps)
    elif place=='den': den = den + x*X*eps
    return -eps*num/den*np.exp(-i*eps)
